def copy_versions(apps, schema_editor):
    """Carry each session's "what changed when" map (discovery._mutation_versions)
    into ProjectDomainVersion rows, so no database loses its version history."""
    from datetime import datetime

    Session = apps.get_model("consistency", "ConsistencySession")
    Version = apps.get_model("consistency", "ProjectDomainVersion")
    Project = apps.get_model("projects", "Project")
    live = set(Project.objects.values_list("pk", flat=True))
    for sess in Session.objects.all():
        versions = (sess.discovery or {}).get("_mutation_versions") or {}
        if sess.project_id not in live or not isinstance(versions, dict):
            continue
